  mul_v1 u00 (.a(a0), .w(w0), .p(p00));
  mul_v1 u01 (.a(a0), .w(w1), .p(p01));
  mul_v1 u10 (.a(a1), .w(w0), .p(p10));
  mul_v1 u11 (.a(a1), .w(w1), .p(p11));
  assign d00 = c00 + {{4{p00[8]}}, p00};
  assign d01 = c01 + {{4{p01[8]}}, p01};
  assign d10 = c10 + {{4{p10[8]}}, p10};
  assign d11 = c11 + {{4{p11[8]}}, p11};
endmodule
